{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "The closest retrieved analogue, a thiazole-containing heteroaromatic (852A), showed approximately 27% oral bioavailability in patients, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alpelisib, a thiazole/heteroaromatic amide with a tert-butyl substituent, had 50–60% oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Dasatinib, a thiazole carboxamide with a basic amine, had 34% absolute oral bioavailability in humans, above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Flecainide, a piperidine-containing benzamide, had about 95% oral bioavailability in humans, supporting high F for a piperidine amide chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Meloxicam, a heteroaromatic amide, had 89% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple structurally related heteroaromatic amides and piperidine-containing drugs have oral bioavailability values at or above 20%, mostly 27–99%, and no affirmative threshold-relevant evidence supports F < 20%.",
  "evidence_gaps": [
    "No close analogue with Morgan similarity above 0.3 was retrieved; all similarities are below 0.24, limiting direct transferability.",
    "Dasatinib records include conflicting descriptions of low versus high bioavailability, though numeric absolute values remain at or above 20%.",
    "The naltrexone record reports a wide 5–40% range and is not threshold-resolved for F >= 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

